        "tarea": "Revisión de Ventilación Materiales necesarios: Aspiradora de mano o aire comprimido. Procedimiento: 1. Apagar el monitor y desconectarlo de la fuente de alimentación. 2. Usar una aspiradora de mano o aire comprimido para limpiar las rejillas de ventilación del monitor, asegurándose de que no estén bloqueadas por polvo o suciedad.",
        "frecuencia": "Trimestral",
        "estado": "PENDIENTE",
        "fecha": "",
