        "tarea": "Limpieza Regular: Herramientas necesarias: Paño de microfibra, alcohol isopropílico. Procedimiento: Después de cada uso, limpiar el antropómetro con un paño de microfibra ligeramente humedecido con alcohol isopropílico. Asegúrarse de secar completamente el instrumento antes de guardarlo para evitar cualquier tipo de corrosión o acumulación de residuos.",
        "frecuencia": "Diario",
