        "equipo": "Multímetro",
        "tarea": "Comprobación de la Pantalla: Asegúrate de que la pantalla esté libre de grietas y sea legible. Si la pantalla muestra fallos o está dañada, es posible que necesite ser reparada o reemplazada.",
        "frecuencia": "Diario",
        "estado": "PENDIENTE",
        "fecha": "",
