        "equipo": "Multímetro",
        "tarea": "Pruebas de Funcionamiento: Realiza pruebas de funcionamiento básicas para asegurarte de que el multímetro mide correctamente. Esto incluye probar diferentes rangos y funciones (como voltaje, corriente y resistencia).",
        "frecuencia": "Semanal",
